// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Earth".

Having recently reread 2001 - A Space Odyssey
by Arthur C. Clarke, the term Earth immediately
brought the monolith to mind. How else could
the term, or language in general, which gives
names to things, have come about if the monolith
had not existed? Ok, just a theory... (and a
good excuse to model the scene I always wanted to do) 🤷‍♂️😇😂
*/

let theShader, moves=[0,0], dpr = Math.max(1, 0.5 * window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return;
	moves[0]+=((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
	moves[1]+=((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2635860/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	canvas.style = canvasStyle;
}

function draw() {
  shader(theShader);
	mouseMove();
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
	theShader.setUniform("move", moves);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
// fast (unprecise) 2D rotation
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// simple color palette - param a can be float or vec3
#define hue(a) (.24+.4*cos(6.3*(a)+vec3(0,83,21)))
// restrict the ray marcher to 1000 units of depth
#define MAXD 1000.
#define mapto(x,a,b,c,d) ((x-a)/(b-a)*(d-c)+c)
// convert color a to sepia
#define sepia(a) vec3(dot(a,vec3(.4,.8,.2)),dot(a,vec3(.3,.6,.2)),dot(a,vec3(.2,.5,.1)))
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1., h=.0;
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p);
		p*=2.3;
		a*=.35;
		h+=a;
	}
	return t/h;
}
// Returns a sky dome full of stars (animated)
vec3 sky(vec2 p, bool anim) {
	p.x-=.17-(anim?2e-4*T:.0);
	p*=500.;
	vec2 id=floor(p), gv=fract(p)-.5;
	float n=rnd(id), d=length(gv);
	if (n<.95) return vec3(0);
	return vec3(S(3e-2*n,1e-3*n,d*d));
}
// Returns the distance to a 3D box at point p with the dimension s
// and an implicit corner radius of 5e-2 units
float box(vec3 p, vec3 s) {
	p=abs(p)-s+.05;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z))-.05;
}
// Returns the distance to a rocky terrain at the given point
float terrain(vec3 p) {
	const float k=10.;
	float e=fbm(fbm(p.xz*.2+vec2(8,2))+p.xz*.2+vec2(1,-2));
	e=600.*e+600.;
	e=mapto(e,.0,k,.0,1.);
	e=k*e;
	e=mapto(e,.0,k,.0,1.);
	return .22*(e*.1+1.);
}
// Returns the distance to an egg shaped stone at point p with dimension s
float stone(vec3 p, vec3 s) {
	s.xz += (-p.y*.085);
	s = abs(s);
	return (length(p / s) - 1.) * min(min(s.x, s.y), s.z);
}
// Returns the distance to a stack of stones at point p
float stones(vec3 p) {
	vec2 k=vec2(-1,1);
	float d=min(min(min(
		stone((p+vec3(3.25,3.3,3))*k.yxy,vec3(.7,.4,.4)),
		stone((p+vec3(3.25,2.65,3))*k.yxy,vec3(.5,.3,.3))),
		stone((p+vec3(3.25,2.2,3))*k.yxy,vec3(.3,.2,.4))),
		stone((p+vec3(3.25,1.85,3))*k.yxy,vec3(.3,.15,.2)));
	return d*.8;
}
// Returns the distance to the scene at point p and its associated object-id
vec2 map(vec3 p) {
	float
	bx=box(p+vec3(1,2,-3),vec3(3,9,1)),
	fl=p.y+terrain(p);
	fl=min(fl*.4,stones(p));
	vec2 a=vec2(bx,1), b=vec2(fl,0);
	a=a.x<b.x?a:b;
	return a;
}
// Returns the normal of the surface at the given point
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).x+
		k.yxy*map(p+k.yxy*h).x+
		k.yyx*map(p+k.yyx*h).x+
		k.xxx*map(p+k.xxx*h).x
	);
}
// Raymarcher
vec2 march(inout vec3 p, vec3 rd) {
	vec2 dd=vec2(0);
	for (float i=min(.0,time); i<80.; i++) {
		vec2 d=map(p);
		dd.y=d.y;
		if (abs(d.x)<1e-3 || d.x>MAXD) break;
		p+=rd*d.x;
		dd.x+=d.x;
	}
	return dd;
}
// Returns a hatched texture for the given point with the given brightness
float texh(vec2 p, float s) {
	p*=4.;
	float d=1.;
	for (float i=.0; i<10.; i++) {
	float n=noise(p*vec2(1.25,25));
		n=S(-s*.1,2.3-s*.1,n);
		d=min(d,1.-n);
		p+=.07;
		p*=1.2;
		p=p.yx;
		if (s<i) break;
	}
	return 1.-d;
}
// Returns the shadow value of the given point with the given light position
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=normalize(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i).x;
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,128.*d/i);
		i+=d;
	}
	return shd;
}
// Returns the amount of ambient occlusion at the given point
float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for (float i=.0; i<5.; i++) {
		float
		h=.01+i*.09,
		d=map(p+h*n).x;
		occ+=(h-d)*sca;
		sca*=.55;
		if (occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}
// Renders the scene
vec3 render(inout vec3 p, vec3 rd) {
	// initialize the color vectors (c is a placeholder for performance reasons)
	vec3 col=vec3(0), c=col;
	// get the distance to the scene at point p and ray direction rd
	vec2 d=p.y>3.?vec2(MAXD,-1):march(p,rd);
	// distinguish between sky and everything else
	if (d.x<MAXD) {
		// ray has hit the scene, so calculate the normal and place the light
		vec3 n=norm(p), lp=vec3(0,3,-10), l=N(lp-p);
		// calculate diffuse, fresnel, shadow, ambient occlusion and the light's attenuation
		float dif=clamp(dot(l,n),.0,1.),
		fres=pow(clamp(1.+dot(rd,n),.0,1.),5.),
		shad=shadow(p+n*5e-2,lp),
		occl=calcAO(p,n),
		ldst=max(length(lp-p), 1e-3),
		attn=2./(1.+ldst*.25+ldst*ldst*.025);
		// basic illumination of the scene
		col+=.85*dif*attn*shad;
		// add shadows as effect of the texture
		dif=dif*attn+shad;
		// apply the hatch effect as a cube map to the scene
		c+=texh(p.xy,dif)*abs(n.z);
		c+=texh(p.xz,dif)*abs(n.y);
		c+=texh(p.yz,dif)*abs(n.x);
		// exclude the monolith from texturing with hatches
		if (d.y<1.) {
			col+=.08+c;
			col=sepia(col);
		} else {
			col=mix(col*.5,vec3(1),fres);
		}
		// apply once again ambient occlusion to the scene to enhance the effect
		col=mix(vec3(.2),col,1.2*occl);
	}
	// apply distance fog to the scene
	col=mix(vec3(0),col,exp(-125e-6*d.x*d.x*d.x));
	// apply the starry sky
	if (d.x>=30.) {
		vec2 sn=.5+vec2(atan(rd.x,rd.z),atan(length(rd.xz),rd.y))/6.28318;
		sn*=.5;
		col=vec3(sky(sn,true)+sky(2.+sn*2.,true)+sky(9.9+sn*3.,false));
	}
	return col;
}
// Rotates the camera
void cam(inout vec3 p) {
	p.xz*=rot(.42-move.x*6.3/MN);
}
// The main entry of the fragment shader
void main() {
	// calculate the unit vector
	vec2 uv=(FC-.5*R)/MN;
	// initialize the color vector
	vec3 col=vec3(0),
	// place the camera 10 units behind the scene and 3 units above
	p=vec3(0,3,-10),
	// zoom out a fair bit (fish-eye lens effect)
	rd=N(vec3(uv,.5));
	// rotate the canmera around the scene's center
	cam(p); cam(rd);
	// render the scene (animate the revealing)
	col=mix(col,render(p,rd),min(time*.3,1.));
	// vignette (dimensions of the window, normalized)
	uv=FC/R*2.-1.;
	// narrow the frame
	uv*=.7;
	// calculate the distance to the vignette and soften the transition
	float v=pow(dot(uv,uv),1.8);
	// darken the corners (yes absolute black leads to the desired result)
	col=mix(col,vec3(0),v);
	// fade in the darkest parts from black to dark gray
	col=max(col,mix(.0,.08,min(time*.3,1.)));
	// output the pixel's color
	O=vec4(col,1);
}

